const before = await client.items.find<Schema.Article>("article-1", { nested: true });
const originalBody = JSON.stringify(before.body);
if (!before.body.en) throw new Error("English Structured Text is missing.");
let greetingMatches = 0;
let blockMatches = 0;
const english = mapNodes(before.body.en, (node) => {
  if (isSpan(node) && node.value === "Hello reader") {
    greetingMatches += 1;
    return { ...node, value: "Welcome reader" };
  }
  if (isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1") {
    blockMatches += 1;
    return {
      ...node,
      item: buildBlockRecord<Schema.ImageBlock>({
        id: node.item.id,
        ...node.item.attributes,
        caption: "Summer portrait",
      }),
    };
  }
  return node;
});
if (greetingMatches !== 1 || blockMatches !== 1) {
  throw new Error("Expected exactly one greeting span and one image block.");
}
english.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});
if (JSON.stringify(before.body) !== originalBody) {
  throw new Error("The original snapshot was unexpectedly modified.");
}
const expectedBody = { ...before.body, en: english };
await client.items.update<Schema.Article>(before.id, {
  body: expectedBody,
  meta: { current_version: before.meta.current_version },
});
const after = await client.items.find<Schema.Article>(before.id, { nested: true });
if (JSON.stringify(after.body) !== JSON.stringify(expectedBody)) {
  throw new Error("Saved Structured Text differs from the expected content.");
}
if (after.id !== before.id || after.title !== before.title || after.untouched !== before.untouched) {
  throw new Error("An unrelated record field changed.");
}
if (JSON.stringify(after.body.it) !== JSON.stringify(before.body.it)) {
  throw new Error("Italian locale changed.");
}
if (after.meta.status !== "draft") {
  throw new Error("Expected the article to remain a draft.");
}
console.log({ verified: true, article: after });

try {
  const before = await client.items.find<Schema.Article>("article-1", { nested: true, version: "current" });
  if (!before.body.en) throw new Error("English Structured Text is empty.");
  const originalRecord = JSON.stringify(before);
  let greetingMatches = 0;
  let blockMatches = 0;
  const english = mapNodes(before.body.en, (node) => {
    if (isSpan(node) && node.value === "Hello reader") {
      greetingMatches += 1;
      return { ...node, value: "Welcome reader" };
    }
    if (isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1") {
      blockMatches += 1;
      return {
        ...node,
        item: buildBlockRecord<Schema.ImageBlock>({
          id: node.item.id,
          ...node.item.attributes,
          caption: "Summer portrait",
        }),
      };
    }
    return node;
  });
  if (greetingMatches !== 1 || blockMatches !== 1) {
    throw new Error("Expected exactly one greeting span and one image block block-1.");
  }
  english.document.children.push({
    type: "paragraph",
    children: [{ type: "span", value: "See you soon." }],
  });
  const body: FieldValueInRequest<typeof before, "body"> = { ...before.body, en: english };
  if (JSON.stringify(before) !== originalRecord) {
    throw new Error("The edit unexpectedly mutated the original snapshot.");
  }
  const expectedBody = JSON.stringify(body);
  await client.items.update<Schema.Article>(before.id, {
    body,
    meta: { current_version: before.meta.current_version },
  });
  const after = await client.items.find<Schema.Article>(before.id, { nested: true, version: "current" });
  const checks = {
    bodyMatchesRequestedEdits: JSON.stringify(after.body) === expectedBody,
    italianPreserved: JSON.stringify(after.body.it) === JSON.stringify(before.body.it),
    otherFieldsPreserved: JSON.stringify({ ...after, body: before.body, meta: before.meta }) === originalRecord,
    publicationStatusPreserved: after.meta.status === before.meta.status,
  };
  console.log({ checks, article: after });
  if (Object.values(checks).some((passed) => !passed)) {
    throw new Error("Post-update preservation verification failed; inspect the reported record before further action.");
  }
} catch (error) {
  console.log({ error: error instanceof Error ? error.message : String(error) });
  throw error;
}

const currentItem = await client.items.find<Schema.Article>("article-1", { nested: true, version: "current" });
if (!currentItem.body.en) throw new Error("English Structured Text is missing.");
const originalEnglish = JSON.stringify(currentItem.body.en);
const originalItalian = JSON.stringify(currentItem.body.it);
let greetingCount = 0;
let blockCount = 0;
const content = mapNodes(currentItem.body.en, (node) => {
  if (isSpan(node) && node.value === "Hello reader") {
    greetingCount += 1;
    return { ...node, value: "Welcome reader" };
  }
  if (isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1") {
    blockCount += 1;
    return {
      ...node,
      item: buildBlockRecord<Schema.ImageBlock>({
        id: node.item.id,
        ...node.item.attributes,
        caption: "Summer portrait",
      }),
    };
  }
  return node;
});
if (greetingCount !== 1 || blockCount !== 1) {
  throw new Error("Expected exactly one greeting span and one block-1; no update made.");
}
if (JSON.stringify(currentItem.body.en) !== originalEnglish) {
  throw new Error("The original English snapshot was unexpectedly modified.");
}
content.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});
const body: FieldValueInRequest<typeof currentItem, "body"> = { ...currentItem.body, en: content };
const expectedFields = JSON.stringify({ ...currentItem, body, meta: undefined });
await client.items.update<Schema.Article>(currentItem.id, {
  body,
  meta: { current_version: currentItem.meta.current_version },
});
const saved = await client.items.find<Schema.Article>(currentItem.id, { nested: true, version: "current" });
if (JSON.stringify({ ...saved, meta: undefined }) !== expectedFields) {
  throw new Error("Saved content differs from the expected record.");
}
if (JSON.stringify(saved.body.it) !== originalItalian) {
  throw new Error("Italian locale changed unexpectedly.");
}
if (saved.meta.status !== currentItem.meta.status || saved.meta.status !== "draft") {
  throw new Error("The record did not retain its draft status.");
}
console.log({
  id: saved.id,
  status: saved.meta.status,
  current_version: saved.meta.current_version,
  verified: "Three English edits saved; all other nodes, fields, marks, link, block identity and image, and Italian locale preserved.",
  article: saved,
});
